create extension if not exists pgcrypto;
create type public.member_role as enum ('admin','reception','professional');
create type public.appointment_status as enum ('pending','confirmed','cancelled','completed','no_show');
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, timezone text not null default 'America/Argentina/Buenos_Aires', created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users on delete cascade, organization_id uuid not null references public.organizations on delete cascade, full_name text not null, role public.member_role not null default 'professional', phone text, created_at timestamptz not null default now());
create table public.locations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, address text, phone text, active boolean not null default true);
create table public.services (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, duration_minutes integer not null check(duration_minutes between 5 and 480), price numeric(12,2) not null default 0, color text not null default '#91c8ff', active boolean not null default true);
create table public.customers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, full_name text not null, document_number text, phone text not null, email text, whatsapp_opt_in boolean not null default false, created_at timestamptz not null default now(), unique(organization_id,document_number));
create table public.appointments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, customer_id uuid not null references public.customers, professional_id uuid references public.profiles, location_id uuid references public.locations, service_id uuid not null references public.services, starts_at timestamptz not null, ends_at timestamptz not null, status public.appointment_status not null default 'pending', notes text, reminder_24h_at timestamptz, created_at timestamptz not null default now(), check(ends_at > starts_at));
create table public.notification_log (id uuid primary key default gen_random_uuid(), appointment_id uuid not null references public.appointments on delete cascade, channel text not null check(channel in ('whatsapp','email')), kind text not null, status text not null, provider_message_id text, payload jsonb, created_at timestamptz not null default now(), unique(appointment_id,channel,kind));
create index appointments_schedule_idx on public.appointments(organization_id,starts_at) where status in ('pending','confirmed');
create index notification_log_status_idx on public.notification_log(status,created_at);
alter table public.organizations enable row level security; alter table public.profiles enable row level security; alter table public.locations enable row level security; alter table public.services enable row level security; alter table public.customers enable row level security; alter table public.appointments enable row level security; alter table public.notification_log enable row level security;
create function public.current_org_id() returns uuid language sql stable security definer set search_path=public as $$ select organization_id from public.profiles where id=auth.uid() $$;
revoke all on function public.current_org_id() from public, anon; grant execute on function public.current_org_id() to authenticated;
create policy organization_members on public.organizations for select to authenticated using (id=(select public.current_org_id()));
create policy profile_members on public.profiles for select to authenticated using (organization_id=(select public.current_org_id()));
create policy location_members on public.locations for all to authenticated using (organization_id=(select public.current_org_id())) with check (organization_id=(select public.current_org_id()));
create policy service_members on public.services for all to authenticated using (organization_id=(select public.current_org_id())) with check (organization_id=(select public.current_org_id()));
create policy customer_members on public.customers for all to authenticated using (organization_id=(select public.current_org_id())) with check (organization_id=(select public.current_org_id()));
create policy appointment_members on public.appointments for all to authenticated using (organization_id=(select public.current_org_id())) with check (organization_id=(select public.current_org_id()));
create policy notification_members on public.notification_log for select to authenticated using (exists(select 1 from public.appointments a where a.id=appointment_id and a.organization_id=(select public.current_org_id())));
create or replace function public.appointments_due_for_reminders() returns table(id uuid,phone text,customer_name text,starts_at timestamptz,service_name text) language sql security definer set search_path=public as $$ select a.id,c.phone,c.full_name,a.starts_at,s.name from appointments a join customers c on c.id=a.customer_id join services s on s.id=a.service_id where a.status='confirmed' and c.whatsapp_opt_in=true and a.starts_at between now()+interval '23 hours' and now()+interval '25 hours' and not exists(select 1 from notification_log n where n.appointment_id=a.id and n.channel='whatsapp' and n.kind='reminder_24h') $$;
revoke all on function public.appointments_due_for_reminders() from public, anon, authenticated;

